// ---- the tests -------------------------------------------------------------------------------------------------------------------------

constexpr std::size_t kOperandCount = sizeof(kOperands) / sizeof(kOperands[0]);

Decimal make(const DecimalBits& b) { return Decimal(b.lo, b.mid, b.hi, (b.flags & 0x80000000u) != 0, static_cast<std::uint8_t>((b.flags >> 16) & 0xFF)); }

std::string hex(unsigned long long v) {
    char buffer[24];
    std::snprintf(buffer, sizeof buffer, "0x%llx", v);
    return buffer;
}

// What the golden prints for a value: the bits in hex (signed integers sign extended to 64 bits), a decimal as its text.
std::string show(const ConstantValue& v) {
    struct Show {
        std::string operator()(std::monostate) const { return "null"; }
        std::string operator()(bool b) const { return hex(b ? 1 : 0); }
        std::string operator()(char16_t c) const { return hex(static_cast<std::uint16_t>(c)); }
        std::string operator()(std::int8_t x) const { return hex(static_cast<unsigned long long>(static_cast<std::int64_t>(x))); }
        std::string operator()(std::int16_t x) const { return hex(static_cast<unsigned long long>(static_cast<std::int64_t>(x))); }
        std::string operator()(std::int32_t x) const { return hex(static_cast<unsigned long long>(static_cast<std::int64_t>(x))); }
        std::string operator()(std::int64_t x) const { return hex(static_cast<unsigned long long>(x)); }
        std::string operator()(std::uint8_t x) const { return hex(x); }
        std::string operator()(std::uint16_t x) const { return hex(x); }
        std::string operator()(std::uint32_t x) const { return hex(x); }
        std::string operator()(std::uint64_t x) const { return hex(x); }
        std::string operator()(float x) const { return hex(std::bit_cast<std::uint32_t>(x)); }
        std::string operator()(double x) const { return hex(std::bit_cast<std::uint64_t>(x)); }
        std::string operator()(const std::u16string&) const { return "string"; }
        std::string operator()(const Decimal& d) const { return d.to_string(); }
    };
    return std::visit(Show{}, v);
}

KnownTypeCode code_of(char c) {
    switch (c) {
        case 'c': return KnownTypeCode::Char;
        case 'a': return KnownTypeCode::SByte;
        case 'b': return KnownTypeCode::Byte;
        case 's': return KnownTypeCode::Int16;
        case 't': return KnownTypeCode::UInt16;
        case 'i': return KnownTypeCode::Int32;
        case 'u': return KnownTypeCode::UInt32;
        case 'l': return KnownTypeCode::Int64;
        case 'm': return KnownTypeCode::UInt64;
        case 'f': return KnownTypeCode::Single;
        case 'd': return KnownTypeCode::Double;
        default: return KnownTypeCode::Decimal;  // 'x'
    }
}

ConstantValue value_of(char from, unsigned long long bits) {
    switch (from) {
        case 'c': return static_cast<char16_t>(bits);
        case 'a': return static_cast<std::int8_t>(bits);
        case 'b': return static_cast<std::uint8_t>(bits);
        case 's': return static_cast<std::int16_t>(bits);
        case 't': return static_cast<std::uint16_t>(bits);
        case 'i': return static_cast<std::int32_t>(bits);
        case 'u': return static_cast<std::uint32_t>(bits);
        case 'l': return static_cast<std::int64_t>(bits);
        case 'm': return static_cast<std::uint64_t>(bits);
        case 'f': return std::bit_cast<float>(static_cast<std::uint32_t>(bits));
        default: return std::bit_cast<double>(static_cast<std::uint64_t>(bits));  // 'd'
    }
}

// The cast with .NET's outcome as text: the value shown, or OVF for an OverflowException.
std::string cast_text(char to, const ConstantValue& v, bool check) {
    try {
        return show(util::csharp_primitive_cast(code_of(to), v, check));
    } catch (const util::OverflowError&) {
        return "OVF";
    }
}

// Collects mismatches so one run shows the first few of them.
struct Mismatches {
    int count = 0;
    std::string first;
    void add(const std::string& what) {
        if (count++ < 12) first += what + "\n";
    }
    void report(int line, int total) const {
        CB_CHECK(count == 0);
        if (count != 0) testing::record_failure(__FILE__, line, std::to_string(count) + " of " + std::to_string(total) + " differ from .NET; the first ones:\n" + first);
    }
};

std::string arithmetic(int op, const Decimal& a, const Decimal& b) {
    try {
        switch (op) {
            case 0: return Decimal::add(a, b).to_string();
            case 1: return Decimal::subtract(a, b).to_string();
            case 2: return Decimal::multiply(a, b).to_string();
            case 3: return Decimal::divide(a, b).to_string();
            case 4: return Decimal::remainder(a, b).to_string();
            default: return std::to_string(Decimal::compare(a, b));
        }
    } catch (const util::OverflowError&) {
        return "OVF";
    } catch (const util::DivideByZeroError&) {
        return "DIV0";
    }
}

CB_TEST("dotnet.decompiler.util.decimal_arithmetic_matches_dotnet", [] {
    const char* const* const grids[6] = {kAdd, kSub, kMul, kDiv, kRem, kCmp};
    const char* const names[6] = {"+", "-", "*", "/", "%", "compare"};
    Mismatches bad;
    int total = 0;
    for (int op = 0; op < 6; op++) {
        for (std::size_t i = 0; i < kOperandCount; i++) {
            for (std::size_t j = 0; j < kOperandCount; j++) {
                const Decimal a = make(kOperands[i]), b = make(kOperands[j]);
                const std::string actual = arithmetic(op, a, b);
                const std::string expected = grids[op][i * kOperandCount + j];
                total++;
                if (actual != expected) bad.add(a.to_string() + " " + names[op] + " " + b.to_string() + ": ours " + actual + ", .NET " + expected);
            }
        }
    }
    bad.report(__LINE__, total);
});

CB_TEST("dotnet.decompiler.util.decimal_negate_and_division_by_zero", [] {
    Mismatches bad;
    for (std::size_t i = 0; i < kOperandCount; i++) {
        const std::string actual = Decimal::negate(make(kOperands[i])).to_string();
        if (actual != kNegate[i]) bad.add("-" + make(kOperands[i]).to_string() + ": ours " + actual + ", .NET " + kNegate[i]);
    }
    bad.report(__LINE__, static_cast<int>(kOperandCount));
    // negating zero flips its sign bit as .NET's Negate does, and the value stays equal to 0
    const Decimal minus_zero = Decimal::negate(Decimal());
    CB_CHECK(minus_zero.negative);
    CB_CHECK(Decimal::compare(minus_zero, Decimal()) == 0);
    CB_CHECK_THROWS_AS(util::DivideByZeroError, Decimal::divide(Decimal(1, 0, 0, false, 0), Decimal()));
    CB_CHECK_THROWS_AS(util::DivideByZeroError, Decimal::remainder(Decimal(1, 0, 0, false, 0), Decimal()));
    CB_CHECK_THROWS_AS(util::OverflowError, Decimal::multiply(make(kOperands[5]), make(kOperands[5])));
    // 1 / 3 and 2 / 3: the 28 digits of the scale limit, rounded to even
    CB_CHECK_EQ(Decimal::divide(Decimal(1, 0, 0, false, 0), Decimal(3, 0, 0, false, 0)).to_string(), std::string("0.3333333333333333333333333333"));
    CB_CHECK_EQ(Decimal::divide(Decimal(2, 0, 0, false, 0), Decimal(3, 0, 0, false, 0)).to_string(), std::string("0.6666666666666666666666666667"));
});

CB_TEST("dotnet.decompiler.util.decimal_conversions_match_dotnet", [] {
    // (decimal)double and (decimal)float
    {
        Mismatches bad;
        for (const DoubleRow& row : kFromDouble) {
            std::string actual;
            try {
                actual = Decimal::from_double(std::bit_cast<double>(row.bits)).to_string();
            } catch (const util::OverflowError&) {
                actual = "OVF";
            }
            if (actual != row.text) bad.add("(decimal)" + hex(row.bits) + ": ours " + actual + ", .NET " + row.text);
        }
        bad.report(__LINE__, static_cast<int>(sizeof(kFromDouble) / sizeof(kFromDouble[0])));
    }
    {
        Mismatches bad;
        for (const FloatRow& row : kFromFloat) {
            std::string actual;
            try {
                actual = Decimal::from_float(std::bit_cast<float>(row.bits)).to_string();
            } catch (const util::OverflowError&) {
                actual = "OVF";
            }
            if (actual != row.text) bad.add("(decimal)" + hex(row.bits) + "f: ours " + actual + ", .NET " + row.text);
        }
        bad.report(__LINE__, static_cast<int>(sizeof(kFromFloat) / sizeof(kFromFloat[0])));
    }
    // decimal to every primitive type, through csharp_primitive_cast in both modes (a decimal cast checks in both)
    {
        Mismatches bad;
        int total = 0;
        const char targets[] = "cabstiulmfd";
        for (std::size_t i = 0; i < kOperandCount; i++) {
            const ConstantValue operand = make(kOperands[i]);
            for (int t = 0; t < 11; t++) {
                for (const bool check : {false, true}) {
                    const std::string actual = cast_text(targets[t], operand, check);
                    total++;
                    if (actual != kDecimalTo[i][t]) bad.add(make(kOperands[i]).to_string() + " to " + targets[t] + ": ours " + actual + ", .NET " + kDecimalTo[i][t]);
                }
            }
        }
        bad.report(__LINE__, total);
    }
});

CB_TEST("dotnet.decompiler.util.primitive_cast_matches_dotnet", [] {
    Mismatches bad;
    int total = 0;
    for (const CastRow& row : kCasts) {
        const ConstantValue source = value_of(row.from, row.bits);
        for (const bool check : {false, true}) {
            const std::string actual = cast_text(row.to, source, check);
            const std::string expected = check ? row.checked_result : row.unchecked_result;
            total++;
            if (actual != expected) {
                bad.add(std::string(1, row.from) + " " + hex(row.bits) + " to " + row.to + (check ? " checked" : " unchecked") + ": ours " + actual + ", .NET " + expected);
            }
        }
    }
    bad.report(__LINE__, total);
    // a null stays null; a cast to the same type returns the value
    CB_CHECK(std::holds_alternative<std::monostate>(util::csharp_primitive_cast(KnownTypeCode::Int32, ConstantValue(), true)));
    CB_CHECK(show(util::csharp_primitive_cast(KnownTypeCode::Int32, ConstantValue(std::int32_t{7}), true)) == "0x7");
});

